preConditionHook:
// EL's Percentile(pct, series, N) per the VERIFIED register row
// (EL_Percentile_Probe.txt / el_percentile_output.txt): copy the window of
// bars 0..N-1 -- current bar INCLUDED -- sort it and linearly interpolate
// at rank = pct*(N-1) between the two adjacent sorted values (Excel
// PERCENTILE.INC; duplicates are interpolated across, {2,2,4,4} median = 3).
// pct is a 0..1 FRACTION; out of range returns EL's -1 sentinel (measured
// at pct = 25). The window is the close SERIES, which has real
// pre-first-bar history, so no zero-fill mirror is needed. Interpolation
// temporaries live in block scope; everything at hook scope is a declared
// local so it takes the placement prefix (the AdxBelowThreshold
// unprefixed-temporaries lesson).
// EEC X5: one percentile level of the last N closes; exit the long below it,
// the short above it. Reads no position state -- an exit by placement.
cpxSorted.assign((std::size_t)(int)lookback, 0.0);
for (int i = 0; i < (int)lookback; ++i) cpxSorted[(std::size_t)i] = close[i];
// Insertion sort, ascending, in plain loops -- the only non-EL construct is
// the buffer itself (the AtrRising std::vector precedent). The comparisons
// inside the sort are between tick-grid closes, where the EL tolerance
// cannot bind (differences are 0 or >= 1 tick).
for (int i = 1; i < (int)lookback; ++i) {
    double key = cpxSorted[(std::size_t)i];
    int j = i - 1;
    while (j >= 0 && cpxSorted[(std::size_t)j] > key) {
        cpxSorted[(std::size_t)(j + 1)] = cpxSorted[(std::size_t)j];
        j = j - 1;
    }
    cpxSorted[(std::size_t)(j + 1)] = key;
}
cpxVal = 0.0;
if (exitPercentile < 0.0 || exitPercentile > 1.0) {
    cpxVal = -1.0;
} else {
    double rank = exitPercentile * ((int)lookback - 1);
    int lo = (int)rank;
    double frac = rank - lo;
    cpxVal = cpxSorted[(std::size_t)lo];
    if (frac > 0.0) cpxVal = cpxVal + frac * (cpxSorted[(std::size_t)(lo + 1)] - cpxSorted[(std::size_t)lo]);
}
